package com.rdx.fullscreen.m6aoa;
/** Serialized explicit-event AOA-only experiment. A terminal result cannot cascade into AA. */
public final class M6Controller {
 public enum State {NEW,GATE_CHECK,WAIT_TARGET,TARGET_SEEN,PERMISSION_PENDING,PERMISSION_VERIFIED,OPEN_PENDING,PROTOCOL_PENDING,PROTOCOL_CONFIRMED,IDENTITY_PENDING,IDENTITY_SENT,START_PENDING,START_SENT,WAIT_DETACH,WAIT_REENUM,COMPLETE_STOP_REQUIRED,START_OUTCOME_UNKNOWN,ERROR,CLOSED}
 public enum Verdict {NONE,PASS,FAIL,INCONCLUSIVE}
 public static final long DEVICE_WAIT_MS=300000,PERMISSION_WAIT_MS=60000,DETACH_WAIT_MS=10000,REENUM_WAIT_MS=15000,CONTROL_MS=1000;
 public static final int MAX_TRANSFERS=8;
 private final AndroidUsbEnvironment env;private final M6Journal journal;private final int vendor,product;private final String nonce;private final String[] strings;
 private State state=State.NEW;private Verdict verdict=Verdict.NONE;private String reason="NONE",causation="CAUSATION_UNRESOLVED";private UsbIdentity target;private int transfers,starts,stringIndex,permissionRequests,callbackCount,events;private long phase,begin;private boolean gate,opened;private final java.util.HashSet<String> baselineDevices=new java.util.HashSet<String>();
 public M6Controller(AndroidUsbEnvironment e,M6Journal j,int v,int p,String n){if(e==null||j==null||v!=0x22d9||(p!=0x2769&&p!=0x2765)||n==null||!n.matches("[A-Za-z0-9_-]{16,64}"))throw new IllegalArgumentException("Explicit reviewed normal target");env=e;journal=j;vendor=v;product=p;nonce=n;strings=AoaRequest.identity(j.run);}
 public State state(){return state;}public Verdict verdict(){return verdict;}public String reason(){return reason;}public String causation(){return causation;}public int starts(){return starts;}public int transfers(){return transfers;}public int permissionRequests(){return permissionRequests;}public int callbackCount(){return callbackCount;}public UsbIdentity target(){return target;}
 public boolean terminal(){return state==State.COMPLETE_STOP_REQUIRED||state==State.START_OUTCOME_UNKNOWN||state==State.ERROR||state==State.CLOSED;}
 private void record(String event,String detail)throws Exception{journal.add(env.now()-begin,env.wall(),state.name(),event,detail);}
 private void move(State next,String event)throws Exception{state=next;phase=env.now();record(event,"starts="+starts+",transfers="+transfers);}
 private void closeHandle(){if(opened){opened=false;env.close();}}
 private void finish(Verdict v,String r,String cause){if(terminal())return;closeHandle();verdict=v;reason=r;causation=cause;state=v==Verdict.PASS?State.COMPLETE_STOP_REQUIRED:State.ERROR;try{record("TERMINAL",v.name()+":"+r+":"+cause);}catch(Exception failure){state=State.ERROR;verdict=Verdict.INCONCLUSIVE;reason="EVIDENCE_WRITE_FAILED";}}
 private void failed(Exception e){if(starts>0&&(state==State.START_PENDING||state==State.START_SENT)){closeHandle();state=State.START_OUTCOME_UNKNOWN;verdict=Verdict.INCONCLUSIVE;reason="START_OUTCOME_UNKNOWN";try{record("TERMINAL","INCONCLUSIVE:START_OUTCOME_UNKNOWN");}catch(Exception ignored){}}else finish(Verdict.INCONCLUSIVE,"BOUNDARY_OR_JOURNAL_FAILURE","CAUSATION_UNRESOLVED");}
 public void begin(M5PassProof proof){if(state!=State.NEW)return;begin=env.now();phase=begin;try{journal.load();if(journal.size()!=0){restoreLoaded();return;}move(State.GATE_CHECK,"GATE_CHECK");if(proof==null){finish(Verdict.INCONCLUSIVE,"M5_PROOF_REQUIRED","CAUSATION_UNRESOLVED");return;}gate=true;record("M5_GATE",proof.synthetic?"SYNTHETIC_HOST_TEST":"LIVE_REVIEWED_HASH_"+proof.proofHash);move(State.WAIT_TARGET,"WAIT_TARGET");}catch(Exception e){failed(e);}}
 public void restore(){if(state!=State.NEW)return;try{journal.load();restoreLoaded();}catch(Exception e){state=State.ERROR;verdict=Verdict.INCONCLUSIVE;reason="JOURNAL_UNTRUSTED";}}
 private void restoreLoaded(){boolean pending=false,sent=false;String terminal=null;for(String line:journal.entries()){if(line.contains("|START_INTENT|")){if(pending){state=State.ERROR;verdict=Verdict.INCONCLUSIVE;reason="DUPLICATE_START_JOURNAL";return;}pending=true;starts=1;}if(line.contains("|START_RETURN|"))sent=true;if(line.contains("|TERMINAL|"))terminal=line;}
  if(terminal!=null){state=State.CLOSED;verdict=Verdict.INCONCLUSIVE;reason="PRESERVED_TERMINAL_REVIEW_JOURNAL";}else if(pending&&!sent){state=State.START_OUTCOME_UNKNOWN;verdict=Verdict.INCONCLUSIVE;reason="START_OUTCOME_UNKNOWN";}else{state=State.CLOSED;verdict=Verdict.INCONCLUSIVE;reason=sent?"START_ALREADY_SENT_NO_RETRY":"INTERRUPTED_NO_AUTOMATIC_RESUME";}closeHandle();
 }
 public void permissionCallback(String token,UsbIdentity device,boolean granted){if(terminal()||state!=State.PERMISSION_PENDING)return;try{if(!nonce.equals(token)||target==null||!target.sameAttachment(device)){record("INVALID_CALLBACK","ignored");return;}if(env.now()-phase>PERMISSION_WAIT_MS){finish(Verdict.INCONCLUSIVE,"PERMISSION_TIMEOUT","CAUSATION_UNRESOLVED");return;}if(callbackCount!=0)return;callbackCount++;record("PERMISSION_CALLBACK",granted?"granted":"denied");if(!granted){finish(Verdict.INCONCLUSIVE,"PERMISSION_DENIED","CAUSATION_UNRESOLVED");return;}if(!env.hasPermission(target)){finish(Verdict.INCONCLUSIVE,"CALLBACK_PERMISSION_NOT_VERIFIED","CAUSATION_UNRESOLVED");return;}move(State.PERMISSION_VERIFIED,"PERMISSION_VERIFIED");}catch(Exception e){failed(e);}}
 public void step(){if(terminal()||state==State.NEW)return;try{
  if(++events>2048||env.now()<begin||env.now()-begin>420000){finish(Verdict.INCONCLUSIVE,"EVENT_OR_TIME_BOUND","CAUSATION_UNRESOLVED");return;}
  UsbIdentity[] devices=env.inventory();if(devices==null||devices.length>32)throw new IllegalArgumentException("Inventory bound");int normals=0,accessories=0,unknowns=0;UsbIdentity normal=null,accessory=null;boolean current=false;UsbIdentity other=null;
  for(UsbIdentity d:devices){if(d==null)throw new IllegalArgumentException("Null identity");if(d.kind()==UsbIdentity.Kind.NORMAL_PHONE){normals++;normal=d;}if(d.kind()==UsbIdentity.Kind.ACCESSORY){accessories++;accessory=d;}if(d.kind()==UsbIdentity.Kind.UNKNOWN)unknowns++;if(target!=null&&target.sameAttachment(d))current=true;if(d.kind()==UsbIdentity.Kind.UNKNOWN||d.kind()==UsbIdentity.Kind.NON_TARGET&&target!=null&&!baselineDevices.contains(d.key()))other=d;}
  if(normals>1||accessories>1||normals>0&&accessories>0||unknowns>0&&(normals+accessories>0||unknowns>1)){finish(Verdict.INCONCLUSIVE,"MULTIPLE_PLAUSIBLE_DEVICES","CAUSATION_UNRESOLVED");return;}
  if(starts==0&&accessories>0){finish(Verdict.INCONCLUSIVE,target==null?"ACCESSORY_ALREADY_PRESENT":"EXTERNAL_OR_HONDA_SWITCH_OBSERVED",target==null?"ACCESSORY_ALREADY_PRESENT":"HONDA_OR_OTHER_SWITCH_POSSIBLE");return;}
  if(state==State.WAIT_TARGET){if(unknowns>0){finish(Verdict.INCONCLUSIVE,"UNKNOWN_DEVICE_APPEARED","CAUSATION_UNRESOLVED");return;}if(env.now()-phase>DEVICE_WAIT_MS){finish(Verdict.INCONCLUSIVE,"TARGET_NOT_SEEN","CAUSATION_UNRESOLVED");return;}if(normal!=null&&normal.vendorId==vendor&&normal.productId==product){target=normal;for(UsbIdentity d:devices)baselineDevices.add(d.key());record("TARGET",target.key());record("TARGET_METADATA","interfaces="+target.interfaces+",endpoints="+target.endpoints+",serial_not_collected=true");move(State.TARGET_SEEN,"TARGET_SEEN");}else if(env.now()-phase>=DEVICE_WAIT_MS)finish(Verdict.INCONCLUSIVE,"TARGET_NOT_SEEN","CAUSATION_UNRESOLVED");return;}
  if(state==State.WAIT_DETACH){if(env.now()-phase>DETACH_WAIT_MS){finish(Verdict.INCONCLUSIVE,"NO_DETACH","CAUSATION_UNRESOLVED");return;}if(!current){record("DETACH",target.key());move(State.WAIT_REENUM,"WAIT_REENUM");if(accessory!=null)acceptAccessory(accessory);}else if(env.now()-phase>=DETACH_WAIT_MS)finish(Verdict.INCONCLUSIVE,"NO_DETACH","CAUSATION_UNRESOLVED");return;}
  if(state==State.WAIT_REENUM){if(env.now()-phase>REENUM_WAIT_MS){finish(Verdict.INCONCLUSIVE,"TARGET_DISAPPEARED_TIMEOUT","CAUSATION_UNRESOLVED");return;}if(accessory!=null){acceptAccessory(accessory);return;}if(normal!=null){finish(Verdict.INCONCLUSIVE,"NORMAL_DEVICE_REAPPEARED","CAUSATION_UNRESOLVED");return;}if(other!=null){finish(Verdict.INCONCLUSIVE,"UNKNOWN_DEVICE_APPEARED","CAUSATION_UNRESOLVED");return;}if(env.now()-phase>=REENUM_WAIT_MS)finish(Verdict.INCONCLUSIVE,"TARGET_DISAPPEARED_TIMEOUT","CAUSATION_UNRESOLVED");return;}
  if(!current){finish(Verdict.INCONCLUSIVE,"DETACH_BEFORE_CUSTOM_START","HONDA_OR_OTHER_SWITCH_POSSIBLE");return;}
  if(state==State.PERMISSION_PENDING){if(env.now()-phase>=PERMISSION_WAIT_MS)finish(Verdict.INCONCLUSIVE,"PERMISSION_TIMEOUT","CAUSATION_UNRESOLVED");return;}
  if(state==State.TARGET_SEEN){if(env.hasPermission(target))move(State.PERMISSION_VERIFIED,"PERMISSION_VERIFIED");else{if(permissionRequests!=0)throw new IllegalStateException("Permission once");permissionRequests++;move(State.PERMISSION_PENDING,"PERMISSION_REQUEST_INTENT");env.requestPermission(target,nonce);record("PERMISSION_REQUEST_RETURN","once");}return;}
  if(!gate||!env.hasPermission(target)){finish(Verdict.INCONCLUSIVE,"PERMISSION_LOST_OR_GATE","CAUSATION_UNRESOLVED");return;}
  switch(state){
   case PERMISSION_VERIFIED: move(State.OPEN_PENDING,"OPEN_PENDING");break;
   case OPEN_PENDING: if(target.kind()!=UsbIdentity.Kind.NORMAL_PHONE)throw new IllegalStateException("No accessory open");env.open(target);opened=true;move(State.PROTOCOL_PENDING,"OPENED_ONCE");break;
   case PROTOCOL_PENDING: AndroidUsbEnvironment.Result p=send(AoaRequest.protocol(),false);if(p==null)return;int version=AoaRequest.version(p.data(),p.returned);record("PROTOCOL","version="+version);if(version!=1&&version!=2){finish(Verdict.FAIL,"UNSUPPORTED_PROTOCOL","CAUSATION_UNRESOLVED");return;}move(State.PROTOCOL_CONFIRMED,"PROTOCOL_CONFIRMED");break;
   case PROTOCOL_CONFIRMED:move(State.IDENTITY_PENDING,"IDENTITY_PENDING");break;
   case IDENTITY_PENDING:if(send(AoaRequest.string(stringIndex,strings[stringIndex]),false)==null)return;stringIndex++;if(stringIndex==6)move(State.IDENTITY_SENT,"IDENTITY_SENT");break;
   case IDENTITY_SENT:move(State.START_PENDING,"READY_FOR_START");break;
   case START_PENDING:if(starts!=0)throw new IllegalStateException("START once");starts=1;record("START_INTENT","attempt=1");if(send(AoaRequest.start(),true)==null)return;move(State.START_SENT,"START_RETURN");closeHandle();move(State.WAIT_DETACH,"WAIT_DETACH");break;
   case START_SENT:move(State.WAIT_DETACH,"WAIT_DETACH");break;
   default:throw new IllegalStateException("Invalid active state");
  }
 }catch(Exception e){failed(e);}}
 private AndroidUsbEnvironment.Result send(AoaRequest request,boolean start)throws Exception{
  if(!gate||!opened||!env.hasPermission(target)||transfers>=MAX_TRANSFERS||request.code!=51&&request.code!=52&&request.code!=53)throw new IllegalStateException("Transfer gate");
  transfers++;record("TRANSFER_INTENT","code="+request.code+",index="+request.index+",length="+request.length+",sha="+M6Journal.hash(request.payload()));
  AndroidUsbEnvironment.Result r=env.transfer(request);if(r==null)throw new IllegalStateException("No transfer result");record("TRANSFER_RETURN","code="+request.code+",returned="+r.returned+",duration="+r.durationMs+",status="+r.status.name());
  if(r.status!=AndroidUsbEnvironment.Status.ACCEPTED||r.returned!=request.length||r.durationMs>CONTROL_MS){finish(r.status==AndroidUsbEnvironment.Status.REJECTED?Verdict.FAIL:Verdict.INCONCLUSIVE,start?"START_NOT_CONFIRMED":"TRANSFER_NOT_CONFIRMED","CAUSATION_UNRESOLVED");return null;}return r;
 }
 private void acceptAccessory(UsbIdentity d)throws Exception{if(d.generation<=target.generation){finish(Verdict.INCONCLUSIVE,"STALE_ACCESSORY_GENERATION","CAUSATION_UNRESOLVED");return;}record("ACCESSORY_REENUM",d.key());finish(Verdict.PASS,"BOUNDED_AOA_SEQUENCE_AND_REENUM_OBSERVED","CUSTOM_START_ASSOCIATED_NOT_EXCLUSIVE_CAUSATION");}
 public void close(){if(terminal()){closeHandle();return;}finish(Verdict.INCONCLUSIVE,"LOCAL_STOP","CAUSATION_UNRESOLVED");state=State.CLOSED;}
}
